<section id="resultadoRelatorio" class="mt-4">
  <div class="row g-3 mb-3">
    <div class="col-12 col-sm-6 col-lg"><div class="relatorioResumoCard"><div class="relatorioResumoLabel">Saldo anterior</div><div class="relatorioResumoValor text-<?= ($resumo->saldoAnterior ?? 0) < 0 ? 'danger' : 'success' ?>"><?= $moeda($resumo->saldoAnterior ?? 0) ?></div><div class="small text-muted mt-2">Base antes do período</div></div></div>
    <div class="col-12 col-sm-6 col-lg"><div class="relatorioResumoCard"><div class="relatorioResumoLabel">Entradas do período</div><div class="relatorioResumoValor text-success"><?= $moeda($resumo->entradas ?? 0) ?></div><div class="small text-muted mt-2">Valores recebidos</div></div></div>
    <div class="col-12 col-sm-6 col-lg"><div class="relatorioResumoCard"><div class="relatorioResumoLabel">Saídas do período</div><div class="relatorioResumoValor text-danger"><?= $moeda($resumo->saidas ?? 0) ?></div><div class="small text-muted mt-2">Valores pagos</div></div></div>
    <div class="col-12 col-sm-6 col-lg"><div class="relatorioResumoCard"><div class="relatorioResumoLabel">Resultado líquido</div><div class="relatorioResumoValor text-<?= ($resumo->saldo ?? 0) < 0 ? 'danger' : 'success' ?>"><?= $moeda($resumo->saldo ?? 0) ?></div><div class="small text-muted mt-2">Entradas - saídas</div></div></div>
    <div class="col-12 col-sm-6 col-lg"><div class="relatorioResumoCard"><div class="relatorioResumoLabel">Saldo final do período</div><div class="relatorioResumoValor text-<?= ($resumo->saldoFinal ?? 0) < 0 ? 'danger' : 'success' ?>"><?= $moeda($resumo->saldoFinal ?? 0) ?></div><div class="small text-muted mt-2">Saldo anterior + resultado</div></div></div>
  </div>
  <div class="row g-3 mb-4">
    <div class="col-12 col-lg-8"><div class="relatorioResumoPainel h-100"><div class="row g-3"><div class="col-6"><div class="relatorioResumoLabel">Movimentações encontradas</div><div class="fw-bold text-phsa"><?= (int) ($resumo->quantidade ?? 0) ?></div></div><div class="col-6"><div class="relatorioResumoLabel">Movimentações exibidas</div><div class="fw-bold text-phsa"><?= (int) ($resumo->quantidadeExibida ?? 0) ?></div></div><div class="col-6"><div class="relatorioResumoLabel">Campo de data</div><div class="fw-bold text-phsa"><?= $e($campoData[$filtros->campoData ?? 'lan_dtbaixa'] ?? 'Baixa do lançamento') ?></div></div><div class="col-6"><div class="relatorioResumoLabel">Limite de exibição</div><div class="fw-bold text-phsa"><?= ($filtros->limit ?? '') === 'sem_limite' ? 'Sem limite' : number_format((int) ($filtros->limit ?? 0), 0, ',', '.') . ' registros' ?></div></div><div class="col-12 small text-muted mt-2"><?php if (($resumo->quantidadeExibida ?? 0) < ($resumo->quantidade ?? 0)): ?>A tabela exibe os primeiros registros conforme a ordenação selecionada.<?php else: ?>Todas as movimentações encontradas estão sendo exibidas na tabela.<?php endif; ?></div></div></div></div>
    <div class="col-12 col-lg-4"><div class="relatorioResumoPainel h-100"><div class="relatorioResumoLabel">Ordenação aplicada</div><div class="fw-bold text-phsa mb-2"><?= $e($ordenacaoAplicada[0]) ?></div><div class="small text-success"><?= $e($ordenacaoAplicada[1]) ?></div></div></div>
  </div>
  <div class="d-flex justify-content-between align-items-center mb-2"><h5 class="mb-0 text-phsa">Movimentações baixadas</h5><span class="small text-muted"><?= (int) ($resumo->quantidade ?? 0) ?> registro(s)</span></div>
  <div class="table-responsive"><table id="tableRelatorio" class="table table-sm table-striped table-hover align-middle relatorioExtratoTabela"><thead><tr><th>Título</th><th class="text-center">Anexo</th><th class="text-center">Natureza</th><th class="text-center">Data baixa</th><th class="text-end">Valor baixado</th><th class="text-end">Saldo</th></tr></thead><tbody>
    <tr class="table-light fw-semibold"><td colspan="5">Saldo anterior à listagem exibida</td><td class="text-end text-<?= ($resumo->saldoAnterior ?? 0) < 0 ? 'danger' : 'success' ?>"><?= $moeda($resumo->saldoAnterior ?? 0) ?></td></tr>
    <?php if (!$linhas): ?><tr><td colspan="6" class="text-center text-muted py-4"><i class="fa-solid fa-circle-info"></i>&nbsp;Nenhum lançamento encontrado para os filtros informados.</td></tr><?php endif; ?>
    <?php foreach ($linhas as $linha): ?><?php
      $entrada = ($linha->lan_natureza ?? '') === 'Entrada';
      $tituloId = (int) ($linha->lan_idtitulo ?? 0);
      $isTransferencia = ($linha->lan_tipo ?? '') === 'Transferencia';
      $transferenciaId = $isTransferencia
        ? ($entrada ? (int) ($linha->lan_idlancamento_vinculado ?? 0) : (int) ($linha->lan_id ?? 0))
        : 0;
      $tituloNome = trim((string) ($linha->tit_nome ?? '')) ?: trim((string) ($linha->lan_descricao ?? 'Lançamento'));
      $identificacao = '#' . (int) ($linha->lan_id ?? 0) . ' - ' . $tituloNome;
      $urlTitulo = $transferenciaId > 0
        ? Helpers::url('financeiro/transferencia/form/' . $transferenciaId)
        : ($tituloId > 0 ? Helpers::url('titulo/form/' . $tituloId) : '');
      $podeGerenciarAnexoLinha = !$isTransferencia || !$entrada;
      $detalhes = array_filter([trim((string) ($linha->lan_ctf_nome ?? '')), trim((string) ($linha->lan_pct_nome ?? '')), trim((string) ($linha->lan_cdc_nome ?? ''))]);
      $temAnexo = (int) ($linha->arq_id ?? 0) > 0;
      $urlAnexo = $temAnexo ? Helpers::url((string) ($linha->arq_caminho ?? '')) : '';
      $nomeAnexo = $linha->arq_nomeoriginal ?? $linha->arq_nome ?? 'Comprovante';
      $dimensaoAnexo = !empty($linha->arq_largura) && !empty($linha->arq_altura) ? $linha->arq_largura . 'x' . $linha->arq_altura : '—';
    ?><tr>
      <td><div class="fw-semibold text-phsa"><?php if ($urlTitulo !== ''): ?><a class="text-decoration-none" href="<?= $e($urlTitulo) ?>"><?= $e($identificacao) ?></a><?php else: ?><?= $e($identificacao) ?><?php endif; ?></div><div class="small text-muted mt-1"><?= $e(implode(' | ', $detalhes) ?: 'Sem informações complementares') ?></div></td>
      <td class="text-center tdLancamentoAnexoRelatorio"><?php if ($temAnexo): ?><div class="d-flex flex-column align-items-center gap-1"><div class="text-muted text-truncate w-100" title="<?= $e($nomeAnexo) ?>"><?= $e($nomeAnexo) ?></div><div class="text-muted text-truncate w-100 relatorioAnexoDescricao" title="<?= $e($linha->arq_descricao ?? '') ?>"><?= $e($linha->arq_descricao ?? 'Comprovante') ?></div><div class="d-inline-flex gap-1"><a href="<?= $e($urlAnexo) ?>" target="_blank" rel="noopener" class="bto bto-phsa-light btn-sm" title="Visualizar comprovante" aria-label="Visualizar comprovante"><i class="fa-solid fa-eye"></i></a><a href="<?= $e($urlAnexo) ?>" download="<?= $e($nomeAnexo) ?>" class="bto bto-phsa btn-sm" title="Baixar comprovante" aria-label="Baixar comprovante"><i class="fa-solid fa-download"></i></a><?php if ($podeGerenciarAnexoLinha && ($podeTrocarAnexoLancamento ?? false)): ?><button type="button" class="bto bto-phsa-light btn-sm js-substituir-comprovante" data-arquivo-id="<?= (int) $linha->arq_id ?>" data-lancamento-id="<?= (int) $linha->lan_id ?>" title="Trocar comprovante" aria-label="Trocar comprovante"><i class="fa-solid fa-rotate"></i></button><?php endif; ?></div><div class="text-muted text-nowrap relatorioAnexoMeta"><?= $e(strtoupper((string) ($linha->arq_extensao ?? '—'))) ?> | <?= $e(trim(($linha->arq_tamanho ?? '') . ' ' . ($linha->arq_medida ?? '')) ?: '—') ?> | <?= $e($dimensaoAnexo) ?> | <?= $data($linha->arq_dtcad ?? null) ?></div></div><?php elseif ($podeGerenciarAnexoLinha && ($podeAnexarLancamento ?? false)): ?><button type="button" class="bto bto-phsa-light btn-sm js-anexar-comprovante" data-lancamento-id="<?= (int) $linha->lan_id ?>" title="Anexar comprovante" aria-label="Anexar comprovante"><i class="fa-solid fa-paperclip"></i></button><?php else: ?><span class="text-muted">—</span><?php endif; ?></td>
      <td class="text-center"><span class="fw-semibold text-<?= $entrada ? 'success' : 'danger' ?>"><i class="fa-solid <?= $entrada ? 'fa-arrow-trend-up' : 'fa-arrow-trend-down' ?> me-1"></i><?= $entrada ? 'Entrada' : 'Saída' ?></span></td><td class="text-center text-nowrap"><?= $data($linha->lan_dtbaixa ?? null) ?></td><td class="text-end fw-bold text-<?= $entrada ? 'success' : 'danger' ?>"><?= $entrada ? '+' : '-' ?> <?= $moeda($linha->lan_valor ?? 0) ?></td><td class="text-end fw-bold text-<?= ($linha->saldo_acumulado ?? 0) < 0 ? 'danger' : 'success' ?>"><?= $moeda($linha->saldo_acumulado ?? 0) ?></td>
    </tr><?php endforeach; ?>
    <tr class="table-light fw-semibold"><td colspan="5">Saldo ao final da listagem exibida</td><td class="text-end text-<?= ($resumo->saldoFinal ?? 0) < 0 ? 'danger' : 'success' ?>"><?= $moeda($resumo->saldoFinal ?? 0) ?></td></tr>
  </tbody></table></div>
  <div class="d-flex justify-content-end gap-2 flex-wrap mt-4"><button onclick="fgbDatatable('tableRelatorio')" class="bto bto-phsa-light" type="button"><i class="fa-solid fa-diagram-successor"></i>&nbsp;Automatizar tabela</button><button onclick="fgbConverterTabelaEmXlsx('tableRelatorio', 'extratoMovimentacao')" class="bto bto-phsa-light" type="button"><i class="fas fa-file-excel"></i>&nbsp;Exportar para Excel</button><button onclick="fgbGerarImpressao('resultadoRelatorio')" class="bto bto-phsa-light" type="button"><i class="fas fa-print"></i>&nbsp;Imprimir / PDF</button></div>
</section>

<?php $this->push('style'); ?><style>#tableRelatorio.relatorioExtratoTabela .tdLancamentoAnexoRelatorio{width:132px;min-width:132px}.relatorioExtratoTabela .tdLancamentoAnexoRelatorio .text-truncate{max-width:124px;font-size:.62rem}.relatorioExtratoTabela .relatorioAnexoDescricao{font-size:.54rem}.relatorioExtratoTabela .relatorioAnexoMeta{font-size:.5rem}.relatorioExtratoTabela .btn-sm{padding:.2rem .35rem}</style><?php $this->end(); ?>
<?php $this->push('script'); ?><script>$(function(){const salvarUrl='<?= Helpers::url('arquivo/salvarArquivo') ?>',substituirBaseUrl='<?= Helpers::url('arquivo/substituirArquivo') ?>',aceitos='.pdf,.txt,.doc,.docx,.xls,.xlsx,.json,.xml,.jpg,.jpeg,.png,.webp';function enviarComprovante(arquivo,lancamentoId,arquivoId){if(!arquivo||!arquivo.status){swError((arquivo&&arquivo.text)||'Arquivo inválido.');return}const dados={arq_id:0,arq_origem:'lancamento',arq_idorigem:lancamentoId,arq_nome:arquivo.name,arq_nomeoriginal:arquivo.name,arq_tipo:arquivo.isImage?'imagem':'arquivo',arq_base64:arquivo.data};const url=arquivoId?substituirBaseUrl+'/'+arquivoId:salvarUrl;$.ajax({url:url,method:'POST',dataType:'json',data:dados}).done(function(response){swResponse(response);if(response&&response.status)setTimeout(function(){window.location.reload()},500)}).fail(function(){swError('Não foi possível salvar o comprovante.')})}function escolherComprovante(lancamentoId,arquivoId){fgbSelecionarArquivo({customAccept:aceitos,replaceDefault:true,onFileSelect:function(arquivo){enviarComprovante(arquivo,Number(lancamentoId),Number(arquivoId||0))}})}$(document).on('click','.js-anexar-comprovante',function(){escolherComprovante($(this).data('lancamento-id'),0)});$(document).on('click','.js-substituir-comprovante',function(){escolherComprovante($(this).data('lancamento-id'),$(this).data('arquivo-id'))})});</script><?php $this->end(); ?>
